contract_clause(contrato_ocs_0195_2022, clausula_primeira_objeto, 'CLÁUSULA PRIMEIRA – OBJETO', 'O presente Contrato tem por objeto a prestação continuada de serviços de atualização e suporte técnico, na modalidade Software Assurance, do Sistema Gerenciador de Banco de Dados (SGBD) Microsoft SQL Server, conforme especificações constantes do Termo de Referência (Anexo I do Edital do Pregão Eletrônico nº 025/2022 - BNDES) e da proposta apresentada pelo CONTRATADO, respectivamente, Anexos I e II deste Contrato.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_primeira_objeto, objeto, 'prestação continuada de serviços de atualização e suporte técnico, na modalidade Software Assurance, do Sistema Gerenciador de Banco de Dados (SGBD) Microsoft SQL Server', 'trecho_literal').

contract_clause(contrato_ocs_0195_2022, clausula_segunda_vigencia, 'CLÁUSULA SEGUNDA – VIGÊNCIA', 'O presente Contrato terá duração de 36 (trinta e seis) meses, a contar da data de sua assinatura, podendo ser prorrogado, mediante aditivo, por períodos sucessivos, até o limite total de 60 (sessenta) meses. Parágrafo Primeiro O CONTRATADO deverá, no prazo de até 5 (cinco) dias úteis, contados da notificação do Gestor do Contrato, apresentar, por intermédio do seu Representante Legal, sua manifestação sobre a prorrogação do Contrato.  Parágrafo Segundo Independente da notificação do parágrafo anterior, o CONTRATADO deverá comunicar ao Gestor seu interesse quanto à prorrogação do contrato até 90 (noventa) dias antes do término de cada período de vigência contratual.  Parágrafo Terceiro A formalização da prorrogação será efetuada por meio de aditivo epistolar, dispensando-se a assinatura do CONTRATADO  Parágrafo Quarto Caso o CONTRATADO se recuse a celebrar aditivo contratual de prorrogação, tendo antes manifestado sua intenção de prorrogar o Contrato ou deixado de manifestar seu propósito de não prorrogar, nos termos do Parágrafo Primeiro desta Cláusula, ficará sujeito às penalidades previstas na Cláusula de Penalidades deste Contrato.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_segunda_vigencia, prazo_vigencia, '36 meses', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_segunda_vigencia, prazo_maximo_prorrogacao, '60 meses', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_segunda_vigencia, prazo_manifestacao_prorrogacao, '5 dias úteis', 'Parágrafo Primeiro').
contract_clause_fact(contrato_ocs_0195_2022, clausula_segunda_vigencia, prazo_comunicacao_interesse_prorrogacao, '90 dias', 'Parágrafo Segundo').
contract_clause_fact(contrato_ocs_0195_2022, clausula_segunda_vigencia, forma_prorrogacao, 'aditivo epistolar', 'Parágrafo Terceiro').
contract_clause_fact(contrato_ocs_0195_2022, clausula_segunda_vigencia, consequencia_recusa_prorrogacao, 'sujeito às penalidades', 'Parágrafo Quarto').

contract_clause(contrato_ocs_0195_2022, clausula_terceira_local_prazo_condicoes_execucao_objeto, 'CLÁUSULA TERCEIRA – LOCAL, PRAZO E CONDIÇÕES DE EXECUÇÃO DO OBJETO', 'A execução do objeto contratado respeitará as especificações constantes do Termo de Referência (Anexo I deste Contrato) e da proposta apresentada pelo CONTRATADO, respectivamente, Anexos I e II deste Contrato.').
