contract_clause_fact(contrato_ocs_0195_2022, clausula_oitava_equilibrio_economico_financeiro_contrato, documentos_revisao, ['atos normativos', 'lista de preço de fabricantes', 'notas fiscais', 'planilhas de custos unitários'], 'Parágrafo Segundo').
contract_clause_fact(contrato_ocs_0195_2022, clausula_oitava_equilibrio_economico_financeiro_contrato, prazo_solicitacao_reajuste_revisao, 'até a prorrogação ou o encerramento do Contrato', 'Parágrafo Quarto').
contract_clause_fact(contrato_ocs_0195_2022, clausula_oitava_equilibrio_economico_financeiro_contrato, prazo_analise_bndes, '60 dias', 'Parágrafo Quarto').
contract_clause_fact(contrato_ocs_0195_2022, clausula_oitava_equilibrio_economico_financeiro_contrato, consequencia_nao_solicitacao, 'não fará jus aos efeitos retroativos', 'Parágrafo Quarto').
contract_clause_fact(contrato_ocs_0195_2022, clausula_oitava_equilibrio_economico_financeiro_contrato, condicao_prorrogacao_nao_concluida, 'manutenção da proposta do CONTRATADO como a condição mais vantajosa', 'Parágrafo Quinto').
contract_clause_fact(contrato_ocs_0195_2022, clausula_oitava_equilibrio_economico_financeiro_contrato, consequencia_rescisao, 'CONTRATADO fará jus à integralidade dos valores apurados', 'Parágrafo Sexto').

contract_clause(contrato_ocs_0195_2022, clausula_nona_matriz_riscos, 'CLÁUSULA NONA – MATRIZ DE RISCOS', 'O BNDES e o CONTRATADO, tendo como premissa a obtenção do melhor custo contratual mediante a alocação do risco à parte com maior capacidade para geri-lo e absorvê-lo, identificam os riscos decorrentes da relação contratual e, sem prejuízo de outras previsões contratuais, estabelecem os respectivos responsáveis na Matriz de Riscos constante do Anexo III deste Contrato.  Parágrafo Primeiro O reajuste de preço aludido na Matriz de Riscos deve respeitar o disposto na Cláusula de Equilíbrio Econômico-Financeiro deste Contrato.  Parágrafo Segundo É vedada a celebração de aditivos decorrentes de eventos supervenientes alocados, na Matriz de Riscos, como de responsabilidade do CONTRATADO.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_nona_matriz_riscos, anexo_matriz_riscos, 'Anexo III', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_nona_matriz_riscos, reajuste_matriz, 'respeitar o disposto na Cláusula de Equilíbrio Econômico-Financeiro', 'Parágrafo Primeiro').
contract_clause_fact(contrato_ocs_0195_2022, clausula_nona_matriz_riscos, vedacao_aditivos, 'eventos supervenientes alocados, na Matriz de Riscos, como de responsabilidade do CONTRATADO', 'Parág
Segundo').

contract_clause(contrato_ocs_0195_2022, clausula_decima_garantia_contratual, 'CLÁUSULA DÉCIMA – GARANTIA CONTRATUAL', 'O CONTRATADO deverá apresentar garantia contratual, na forma de seguro-garantia, no valor correspondente a 5% (cinco por cento) do valor total do Contrato, em favor do BNDES, com prazo de validade de 36 (trinta e seis) meses, contados da data de assinatura do Contrato, e com vigência mínima de 30 (trinta) dias após o término da vigência contratual, incluindo as prorrogações.  Parágrafo Primeiro A garantia contratual será liberada ou restituída ao CONTRATADO após a execução do objeto e o cumprimento de todas as obrigações contratuais, mediante termo de recebimento definitivo, ressalvadas as hipóteses de retenção previstas neste Contrato.  Parágrafo Segundo A garantia contratual poderá ser executada nas hipóteses de inexecução total ou parcial do objeto, de mora no cumprimento das obrigações contratuais, de inobservância das condições contratuais, de rescisão contratual, de aplicação de multas e de outras obrigações previstas neste Contrato.  Parágrafo Terceiro O BNDES poderá exigir a complementação da garantia contratual, no prazo de 10 (dez) dias úteis, contados da notificação, sempre que o valor da garantia se mostrar insuficiente para cobrir os prejuízos decorrentes da inexecução do Contrato.  Parágrafo Quarto A não apresentação da garantia contratual, no prazo estabelecido, ensejará a rescisão do Contrato, nos termos da Cláusula de Rescisão deste Instrumento.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_garantia_contratual, tipo_garantia, 'seguro-garantia', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_garantia_contratual, valor_garantia, '5%', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_garantia_contratual, prazo_validade_garantia, '36 meses', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_garantia_contratual, vigencia_minima_garantia, '30 dias', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_garantia_contratual, liberacao_garantia, 'após a execução do objeto e o cumprimento de todas as obrigações contratuais', 'Parágrafo Primeiro').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_garantia_contratual, hipoteses_execucao_garantia, ['inexecução total ou parcial do objeto', 'mora no cumprimento das obrigações contratuais', 'inobservância das condições contratuais', 'rescisão contratual', 'aplicação de multas', 'outras obrigações previstas neste Contrato'], 'Parágrafo Segundo').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_garantia_contratual, prazo_complementacao_garantia, '10 dias úteis', 'Parágrafo Terceiro').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_garantia_contratual, consequencia_nao_apresentacao, 'a rescisão do Contrato', 'Parágrafo Quarto').

contract_clause(contrato_ocs_0195_2022, clausula_decima_primeira_obrigações_contratante, 'CLÁUSULA DÉCIMA PRIMEIRA – OBRIGAÇÕES DO CONTRATANTE', 'São obrigações do BNDES: I. efetuar os pagamentos devidos ao CONTRATADO, na forma e condições estabelecidas neste Contrato; II. prestar as informações e os esclarecimentos que lhe forem solicitados pelo CONTRATADO, desde que pertinentes ao objeto contratual; III. notificar o CONTRATADO sobre as ocorrências que possam comprometer a execução do objeto; IV. acompanhar e fiscalizar a execução do Contrato, por intermédio de seus prepostos; V. receber o objeto, por intermédio da Comissão de Recebimento, mencionada na Cláusula Quinta deste Contrato; VI. comunicar ao CONTRATADO, por escrito, as eventuais falhas ou irregularidades constatadas na execução do objeto, fixando-lhe prazo para correção; VII. aplicar as sanções administrativas cabíveis, nos casos de descumprimento das obrigações contratuais; VIII. fornecer ao CONTRATADO os documentos e informações necessárias à execução do objeto, quando solicitados; IX. indicar o Gestor do Contrato, responsável pelo acompanhamento e fiscalização da execução contratual; e X. outras obrigações decorrentes deste Contrato e da legislação aplicável.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_primeira_obrigações_contratante, obrigacoes, ['efetuar os pagamentos', 'prestar as informações', 'notificar o CONTRATADO', 'acompanhar e fiscalizar a execução do Contrato', 'receber o objeto', 'comunicar ao CONTRATADO', 'aplicar as sanções administrativas', 'fornecer ao CONTRATADO os documentos e informações', 'indicar o Gestor do Contrato'], 'trecho_literal').

contract_clause(contrato_ocs_0195_2022, clausula_decima_segunda_obrigações_contratado, 'CLÁUSULA DÉCIMA SEGUNDA – OBRIGAÇÕES DO CONTRATADO', 'São obrigações do CONTRATADO: I. executar o objeto contratado, em estrita conformidade com as especificações constantes do Termo de Referência (Anexo I deste Contrato) e da proposta apresentada, Anexo II deste Contrato; II. manter, durante a vigência do Contrato, todas as condições de habilitação e qualificação exigidas na licitação; III. responder pelos danos causados ao BNDES ou a terceiros, decorrentes de sua culpa ou dolo na execução do Contrato; IV. apresentar, quando solicitado, os documentos e informações necessárias à execução do objeto; V. comunicar ao BNDES, por escrito, qualquer alteração em seus dados cadastrais; VI. manter sigilo sobre as informações confidenciais a que tiver acesso em razão do Contrato; VII. cumprir as normas de segurança e medicina do trabalho; VIII. cumprir as determinações do Gestor do Contrato; IX. apresentar a garantia contratual, na forma e condições estabelecidas neste Contrato; X. substituir, às suas expensas, no prazo de 10 (dez) dias úteis, contados da notificação, os materiais ou serviços que apresentarem vícios ou defeitos; XI. prestar os serviços com presteza, diligência e presteza, em conformidade com as melhores práticas do mercado; XII. apresentar, mensalmente, relatório de acompanhamento da execução do objeto, conforme modelo a ser definido pelo Gestor do Contrato; XIII. apresentar, quando solicitado, os documentos comprobatórios do recolhimento das obrigações sociais e trabalhistas, bem como os comprovantes de pagamento de tributos; XIV. outras obrigações decorrentes deste Contrato e da legislação aplicável.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_segunda_obrigações_contratado, obrigacoes, ['executar o objeto', 'manter as condições de habilitação', 'responder pelos danos', 'apresentar os documentos', 'comunicar ao BNDES', 'manter sigilo', 'cumprir as normas de segurança', 'cumprir as determinações do Gestor do Contrato', 'apresentar a garantia contratual', 'substituir os materiais ou serviços', 'prestar os serviços', 'apresentar, mensalmente, relatório', 'apresentar, quando solicitado, os documentos comprobatórios'], 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_segunda_obrigações_contratado, prazo_substituicao, '10 dias úteis', 'trecho_literal').

contract_clause(contrato_ocs_0195_2022, clausula_decima_terceira_penalidades, 'CLÁUSULA DÉCIMA TERCEIRA – PENALIDADES', 'O descumprimento das obrigações contratuais sujeitará o CONTRATADO, sem prejuízo das demais sanções previstas em lei, às seguintes penalidades: I. advertência; II. multa de mora, calculada na razão de 0,5% (meio por cento) por dia de atraso, sobre o valor da parcela inadimplente, até o limite de 10 (dez) dias. Após esse prazo, a multa será calculada sobre o valor total do Contrato; III. multa de 10% (dez por cento) sobre o valor total do Contrato, em caso de inexecução total do objeto; IV. multa de 5% (cinco por cento) sobre o valor da parcela inadimplente, em caso de inexecução parcial do objeto; V. suspensão temporária de participação em licitação e impedimento de contratar com o BNDES, por prazo não superior a 2 (dois) anos; e VI. declaração de inidoneidade para licitar ou contratar com a Administração Pública, enquanto perdurarem os motivos determinantes da punição ou até a reabilitação perante a própria Administração Pública, que será concedida quando o CONTRATADO ressarcir o BNDES pelos prejuízos resultantes e após decorrido o prazo de 2 (dois) anos da aplicação da penalidade.  Parágrafo Primeiro As multas previstas nos incisos II, III e IV desta Cláusula serão aplicadas cumulativamente, sem prejuízo das demais sanções previstas em lei.  Parágrafo Segundo As sanções previstas nos incisos V e VI desta Cláusula serão aplicadas após a instauração de processo administrativo, assegurados o contraditório e a ampla defesa.  Parágrafo Terceiro As multas serão descontadas dos pagamentos devidos ao CONTRATADO ou cobradas judicialmente.  Parágrafo Quarto A aplicação de qualquer das penalidades previstas nesta Cláusula não impede o BNDES de rescindir o Contrato, nos termos da Cláusula de Rescisão deste Instrumento.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_terceira_penalidades, penalidades, ['advertência', 'multa de mora', 'multa de 10%', 'multa de 5%', 'suspensão temporária', 'declaração de inidoneidade'], 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_terceira_penalidades, multa_mora, '0,5%', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_terceira_penalidades, multa_inexecucao_total, '10%', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_terceira_penalidades, multa_inexecucao_parcial, '5%', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_terceira_penalidades, prazo_suspensao, '2 anos', 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_terceira_penalidades, aplicacao_sanções, 'após a instauração de processo administrativo', 'Parágrafo Segundo').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_terceira_penalidades, forma_cobranca_multas, ['descontadas dos pagamentos', 'cobradas judicialmente'], 'Parágrafo Terceiro').

contract_clause(contrato_ocs_0195_2022, clausula_decima_quarta_rescisao, 'CLÁUSULA DÉCIMA QUARTA – RESCISÃO', 'O presente Contrato poderá ser rescindido, nos termos da legislação aplicável, especialmente da Lei nº 8.666/93 e da Lei nº 13.303/2016, sem prejuízo das demais sanções previstas em lei, nas seguintes hipóteses: I. por ato unilateral do BNDES, nos casos previstos no art. 78 da Lei nº 8.666/93 e no art. 91 da Lei nº 13.303/2016; II. amigavelmente, por acordo entre as partes, reduzido a termo no processo; e III. judicialmente, nos termos da legislação.  Parágrafo Único A rescisão do Contrato, por qualquer motivo, implicará na apuração dos créditos e débitos existentes entre as partes, bem como na aplicação das sanções cabíveis.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_quarta_rescisao, formas_rescisao, ['ato unilateral do BNDES', 'amigavelmente', 'judicialmente'], 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_quarta_rescisao, legislacao_rescisao, ['Lei nº 8.666/93', 'Lei nº 13.303/2016'], 'trecho_literal').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_quarta_rescisao, consequencias_rescisao, ['apuração dos créditos e débitos', 'aplicação das sanções cabíveis'], 'Parágrafo Único').

contract_clause(contrato_ocs_0195_2022, clausula_decima_quinta_gestao_contrato, 'CLÁUSULA DÉCIMA QUINTA – GESTÃO DO CONTRATO', 'A gestão do Contrato será exercida pelo Gestor do Contrato, indicado pelo BNDES, que terá as seguintes atribuições: I. acompanhar e fiscalizar a execução do Contrato; II. dirimir as dúvidas e omissões contratuais; III. analisar e aprovar os relatórios de acompanhamento da execução do objeto; IV. solicitar informações e documentos ao CONTRATADO; V. comunicar ao CONTRATADO as eventuais falhas ou irregularidades constatadas na execução do objeto, fixando-lhe prazo para correção; VI. aplicar as sanções administrativas cabíveis, nos casos de descumprimento das obrigações contratuais; VII. adotar as medidas necessárias para a boa execução do Contrato; VIII. outras atribuições decorrentes deste Contrato e da legislação aplicável.  Parágrafo Único O Gestor do Contrato poderá solicitar o apoio técnico de outros servidores do BNDES, para auxiliar no desempenho de suas atribuições.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_quinta_gestao_contrato, atribuicoes_gestor, ['acompanhar e fiscalizar a execução do Contrato', 'dirimir as dúvidas e omissões contratuais', 'analisar e aprovar os relatórios', 'solicitar informações e documentos', 'comunicar ao CONTRATADO', 'aplicar as sanções administrativas', 'adotar as medidas necessárias'], 'trecho_literal').

contract_clause(contrato_ocs_0195_2022, clausula_decima_sexta_foro, 'CLÁUSULA DÉCIMA SEXTA – FORO', 'Fica eleito o foro da Seção Judiciária do Rio de Janeiro, para dirimir quaisquer dúvidas ou litígios decorrentes do presente Contrato, com renúncia a qualquer outro, por mais privilegiado que seja.').
contract_clause_fact(contrato_ocs_0195_2022, clausula_decima_sexta_foro, foro, 'Seção Judiciária do Rio de Janeiro', 'trecho_literal').
